import styled from '@emotion/styled';

const borderTertiary = '#14141414';

type PortfolioColor = 'megabrands' | 'expansion' | 'sustain' | 'tail';

const portfolioColorStyles: Record<PortfolioColor, { backgroundColor: string }> =
  {
    megabrands: {
      backgroundColor: '#E5B611',
    },
    expansion: {
      backgroundColor: '#C2346A',
    },
    sustain: {
      backgroundColor: '#2F74AA',
    },
    tail: {
      backgroundColor: '#4E579F',
    },
  };

export const StyledContainer = styled.div({
  height: '100%',
  minWidth: '96px',
  maxWidth: '96px',
});

export const StyledImg = styled.img({
  maxHeight: '74px',
  maxWidth: '74px',
  objectFit: 'contain',
});

export const StyledFallback = styled.div({
  maxHeight: '74px',
  maxWidth: '74px',
  textOverflow: 'ellipsis',
  overflow: 'hidden',
  whiteSpace: 'nowrap',
});

interface StyledImgContainerProps {
  $hasPortolioColor?: boolean;
}

export const StyledImgContainer = styled.div<StyledImgContainerProps>(
  ({ $hasPortolioColor }) => ({
    display: 'flex',
    alignItems: 'center',
    position: 'relative',
    minWidth: '96px',
    maxWidth: '96px',
    height: '100%',
    justifyContent: 'space-between',
    ...($hasPortolioColor === false && {
      borderBottom: `1px solid ${borderTertiary}`,
    }),
  }),
);

interface StyledBorderLeftProps {
  $portfolioColor?: string;
}

export const StyledBorderLeft = styled.div<StyledBorderLeftProps>(
  ({ $portfolioColor }) => ({
    height: '100%',
    width: '8px',
    ...($portfolioColor &&
      portfolioColorStyles[$portfolioColor as PortfolioColor]),
  }),
);

interface StyledImgContentProps {
  $hasPortolioColor?: boolean;
}

export const StyledImgContent = styled.div<StyledImgContentProps>(
  ({ $hasPortolioColor }) => ({
    flex: 1,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%',
    width: '100%',
    borderRight: `1px solid ${borderTertiary}`,
    paddingBottom: '5px',
    ...($hasPortolioColor === true && {
      borderBottom: `1px solid ${borderTertiary}`,
    }),
  }),
);
